class ModifiedElementWrapper extends JAnnotatable {
    private List<XmlElement> elements;

    public ModifiedElementWrapper() {}

    public void addElements(List<XmlElement> elements) {
        this.elements = elements;
    }

    @Override
    public String toJAXBString(Options options) throws IOException {
        StringBuilder builder = new StringBuilder();
        builder.append("<");
        for (XmlElement element : elements) {
            builder.append(element.toString());
            if (element.isOptional()) {
                builder.append(" optional=\"yes\"");
            }
        }
        builder.append("/>");
        return builder.toString();
    }
}

